 tray.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-colors')){const expanded=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(expanded));tray.classList.toggle('colors-expanded',expanded);}else if(b.dataset.kind){window.labSound?.('tree');kind=b.dataset.kind;selected='';window.dispatchEvent(new Event('lab:tree-frame'));controls();announce('트리를 눌러 달기');}else if(b.dataset.color)setColor(b.dataset.color);else if(b.hasAttribute('data-add')){const p=window.labPlayerState||treeLayout.arrival;add(Math.atan2(p.z-treeLayout.z,p.x-treeLayout.x),5+Math.random()*19);}else if(b.hasAttribute('data-new')){selected='';controls();announce('트리를 눌러 달기');}else if(b.hasAttribute('data-undo')&&lastAdded&&!busy){busy=true;try{await mutate('DELETE',{id:lastAdded});lastAdded='';selected='';b.disabled=true;await sync();controls();}catch(e){announce(e.message);}finally{busy=false;}}else if(b.hasAttribute('data-close'))close();else if(b.hasAttribute('data-wish')){tray.hidden=true;window.openWishComposer?.({kind,color,fromTree:true});}else if(b.hasAttribute('data-list'))window.openWishList?.();});picker.addEventListener('input',()=>setColor(picker.value,false));picker.addEventListener('change',()=>setColor(picker.value));
